INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 18, 'theory', 'Квиз: CSS — блочная модель, оформление и позиционирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 0, 'Чему равна полная ширина блока при width: 100px, padding: 20px и рамке 2px, если box-sizing не менялся?', '["100px: ширина всегда полная", "140px", "144px", "104px"]', 2, 'По умолчанию width задаёт только содержимое, и к нему добавляются паддинг и рамка с обеих сторон: 100 + 2×20 + 2×2 = 144px. С box-sizing: border-box полная ширина осталась бы равной 100px.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 1, 'Между двумя абзацами: у первого margin-bottom 20px, у второго margin-top 30px. Каким будет расстояние между ними?', '["30px: вертикальные отступы схлопываются, побеждает больший", "50px: отступы складываются", "20px: побеждает первый", "0: отступы взаимно уничтожаются"]', 0, 'Вертикальные марджины соседних блоков схлопываются до большего значения. Горизонтальные не схлопываются никогда, а родителю помогают избежать эффекта паддинг, рамка, flow-root или флекс-контейнер.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 2, 'Почему нельзя просто удалить обводку фокуса через outline: none?', '["Это сломает раскладку: контур занимает место", "Контур нужен браузеру для рисования рамки", "Свойство outline запрещено стандартом", "Человек с клавиатурой перестанет видеть, где находится фокус"]', 3, 'Контур — единственный видимый признак фокуса для тех, кто ходит по странице клавишей Tab. Его можно заменить своим (например, на :focus-visible), но не оставлять элемент без индикации. Раскладку контур не затрагивает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 3, 'Значок нужно прижать к правому верхнему углу карточки. Что для этого нужно?', '["position: fixed у значка", "position: relative у карточки и position: absolute с top и right у значка", "position: sticky у карточки", "float: right у значка"]', 1, 'Абсолютно позиционированный элемент считается от ближайшего предка с position не static. Поэтому карточке ставят relative, чтобы она стала опорной точкой, а значку — absolute и отступы. Без relative значок уехал бы к краю страницы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 4, 'Дочерний элемент имеет z-index: 999, но всё равно оказывается под соседним блоком с z-index: 2. Что могло случиться?', '["z-index больше 100 браузер игнорирует", "Нужно написать !important", "Родитель образует контекст наложения с z-index: 1, и сравниваются родитель с соседом, а не потомок", "У соседа цвет фона светлее"]', 2, 'Родитель с позицией и z-index (а также с opacity меньше единицы или transform) создаёт замкнутый контекст наложения: потомки сравниваются между собой внутри него, а снаружи участвует весь родитель. Поэтому лучше держать небольшую шкалу слоёв.');
